const Achievements=(()=>{
 const storageKey='night-shift-achievements-v1';
 function read(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'null');return data?.version===1&&Number.isInteger(data.highest)&&data.highest>=0&&data.highest<=4?data.highest:0;}catch(e){return 0;}}
 let highest=read();
 function recordWin(game){if(!game?.over||!game.win||game.t<NIGHT||game.achievementRecorded||!Number.isInteger(game.difficulty)||game.difficulty<0||game.difficulty>=MODES.length)return;game.achievementRecorded=true;highest=Math.max(highest,read(),game.difficulty+1);try{localStorage.setItem(storageKey,JSON.stringify({version:1,highest}));}catch(e){}}
 function decorateTitle(heading){if(!heading)return;highest=Math.max(highest,read());heading.querySelector('.achievement-stars')?.remove();if(!highest)return;const stars=document.createElement('span');stars.className='achievement-stars';stars.textContent='★'.repeat(highest);stars.setAttribute('role','img');stars.setAttribute('aria-label','Highest completion: '+MODES[highest-1].n+' ('+highest+' '+(highest===1?'star':'stars')+')');stars.title=MODES[highest-1].n+' completed';heading.append(stars);}
 addEventListener('storage',e=>{if(e.key!==storageKey)return;highest=Math.max(highest,read());if(!G)decorateTitle(document.querySelector('#ov h1'));});return {recordWin,decorateTitle};
})();
const TYPES=['door','light','obj','paint'],LABEL={door:'Door',light:'Lights',obj:'Object',paint:'Painting',fig:'Figure'};
